    internal static int WriteBuckets(GraphBuilder graph, Buckets value)
    {
        return value.Value switch
        {
            LiteralInteger item => WriteLiteralInteger(graph, item),
            ParamInteger item => WriteParamInteger(graph, item),
            _ => throw GraphBuilder.Empty("Buckets"),
        };
    }

    internal static Buckets ReadBuckets(IReadNode node)
    {
        return node.Label switch
        {
            "LiteralInteger" => new Buckets(ReadLiteralInteger(node)),
            "ParamInteger" => new Buckets(ReadParamInteger(node)),
            _ => throw GraphReads.NotACase(node, "Buckets"),
        };
    }

    internal static int WriteCell(GraphBuilder graph, Cell value)
    {
        return value.Value switch
        {
            LiteralInteger item => WriteLiteralInteger(graph, item),
            LiteralIntegerNullable item => WriteLiteralIntegerNullable(graph, item),
            LiteralDecimal item => WriteLiteralDecimal(graph, item),
            LiteralDecimalNullable item => WriteLiteralDecimalNullable(graph, item),
            LiteralString item => WriteLiteralString(graph, item),
            LiteralStringNullable item => WriteLiteralStringNullable(graph, item),
            LiteralBoolean item => WriteLiteralBoolean(graph, item),
