            "LiteralString" => new Separator(ReadLiteralString(node)),
            "ParamString" => new Separator(ReadParamString(node)),
            _ => throw GraphReads.NotACase(node, "Separator"),
        };
    }

    internal static int WriteSubquery(GraphBuilder graph, Subquery value)
    {
        return value.Value switch
        {
            SubqueryQuery item => WriteSubqueryQuery(graph, item),
            SubqueryRows item => WriteSubqueryRows(graph, item),
            SubqueryRecursive item => WriteSubqueryRecursive(graph, item),
            _ => throw GraphBuilder.Empty("Subquery"),
        };
    }

    internal static Subquery ReadSubquery(IReadNode node)
    {
        return node.Label switch
        {
            "SubqueryQuery" => new Subquery(ReadSubqueryQuery(node)),
            "SubqueryRows" => new Subquery(ReadSubqueryRows(node)),
            "SubqueryRecursive" => new Subquery(ReadSubqueryRecursive(node)),
            _ => throw GraphReads.NotACase(node, "Subquery"),
        };
    }

    internal static int WriteWindow(GraphBuilder graph, Window value)
    {
        return value.Value switch
        {
            WindowWithoutFrameWithoutRange item => WriteWindowWithoutFrameWithoutRange(graph, item),
            WindowWithoutFrameWithRangeInteger item => WriteWindowWithoutFrameWithRangeInteger(graph, item),
            WindowWithoutFrameWithRangeDecimal item => WriteWindowWithoutFrameWithRangeDecimal(graph, item),
            WindowWithoutFrameWithRangeDate item => WriteWindowWithoutFrameWithRangeDate(graph, item),
            WindowWithoutFrameWithRangeDatetime item => WriteWindowWithoutFrameWithRangeDatetime(graph, item),
            WindowWithFrame item => WriteWindowWithFrame(graph, item),
            _ => throw GraphBuilder.Empty("Window"),
        };
    }

    internal static Window ReadWindow(IReadNode node)
    {
        return node.Label switch
        {
            "WindowWithoutFrameWithoutRange" =>
                new Window(ReadWindowWithoutFrameWithoutRange(node)),
            "WindowWithoutFrameWithRangeInteger" =>
                new Window(ReadWindowWithoutFrameWithRangeInteger(node)),
            "WindowWithoutFrameWithRangeDecimal" =>
                new Window(ReadWindowWithoutFrameWithRangeDecimal(node)),
            "WindowWithoutFrameWithRangeDate" =>
                new Window(ReadWindowWithoutFrameWithRangeDate(node)),
            "WindowWithoutFrameWithRangeDatetime" =>
                new Window(ReadWindowWithoutFrameWithRangeDatetime(node)),
            "WindowWithFrame" => new Window(ReadWindowWithFrame(node)),
            _ => throw GraphReads.NotACase(node, "Window"),
        };
    }
}
